  // ──────────────────────────────────────────────────────────
  // Lesson 4 · 닮고, 닮지, 젊네요
  //
  // 교재 Pronunciation · 받침 ㄻ
  //
  // ㄻ + 자음 → ㅁ만 발음
  // 닮는 [담는]
  // 젊네요 [점네요]
  //
  // ㄻ + ㄱ/ㄷ/ㅅ/ㅈ
  // 뒤 자음 경음화
  // 닮고 [담꼬]
  // 젊다 [점따]
  // 젊습니다 [점씀니다]
  // 닮지 [담찌]
  // ──────────────────────────────────────────────────────────

